@slots literal
{
  "word": "raspberryrrrx"
}

@answer jsEval
const slots = $slots;
let characters = [...String(slots.word)];
let wanted = "r";
let occurrences = 0;
for (const character of characters) {
  if (character === wanted) {
    occurrences += 1;
  }
}
return occurrences + " times.";

