@slots literal
{
  "holder": "Nadia",
  "balance": 100,
  "interestPerYear": 10,
  "years": 4
}

@answer jsEval
const slots = $slots;
let balance = slots.balance;
for (let year = 0; year < slots.years; year += 1) {
  balance += slots.interestPerYear;
}
return String(balance);

